export const getExportTipsPayrollCsvUrl = (companyId: string,
    params: ExportTipsPayrollCsvParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/companies/${companyId}/tips-payroll/export?${stringifiedParams}` : `/api/companies/${companyId}/tips-payroll/export`
}

